  font-size: 0.78rem;
  font-weight: 500;
  transition: all var(--transition-fast);
  font-family: var(--font-primary);
}
.tf-btn:hover { color: var(--text-primary); }
.tf-btn.active {
  background: var(--accent-blue);
  color: #fff;
}

/* ===== CHART AREA ===== */
.chart-area {
  flex: 1;
  position: relative;
  background: var(--bg-primary);
  min-height: 400px;
}

.chart-area canvas {
  width: 100%;
  height: 100%;
}

/* ===== DETAIL PANEL ===== */
.detail-panel {
  background: var(--bg-secondary);
  border-left: 1px solid var(--border-color);
  overflow-y: auto;
  padding: 0;
}

.detail-section {
  padding: 20px;
  border-bottom: 1px solid var(--border-color);
}

.detail-section h3 {
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--text-bright);
  margin-bottom: 12px;
}

.detail-ticker {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 16px;
}

.detail-ticker-symbol {
  font-size: 1.5rem;
  font-weight: 800;
}

.detail-ticker-name {
  font-size: 0.85rem;
  color: var(--text-secondary);
}

.detail-price {
  font-size: 2rem;
  font-weight: 800;
  font-family: var(--font-mono);
}

.detail-change {
  font-family: var(--font-mono);
  font-weight: 600;
  font-size: 0.95rem;
  margin-top: 4px;
}

.detail-stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.detail-stat-label {
  font-size: 0.72rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.detail-stat-value {
  font-size: 0.88rem;
  font-weight: 600;
  color: var(--text-primary);
}

/* ===== FINANCIALS TABLE ===== */
.financials-table {
  width: 100%;
  border-collapse: collapse;
}

.financials-table td {
  padding: 8px 0;
  font-size: 0.82rem;
  border-bottom: 1px solid var(--border-subtle);
}

.financials-table td:first-child {
  color: var(--text-muted);
  width: 55%;
}

.financials-table td:last-child {
  font-weight: 600;
  text-align: right;
  font-family: var(--font-mono);
}

/* ===== IDEA CARDS ===== */
.ideas-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(340px, 1fr));
  gap: 20px;
}

.idea-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all var(--transition-base);
  cursor: pointer;
}
.idea-card:hover {
  border-color: var(--accent-blue);
  transform: translateY(-2px);
  box-shadow: var(--shadow-lg);
}

.idea-card-header {
  padding: 16px 20px;
  display: flex;
  align-items: center;
  gap: 12px;
  border-bottom: 1px solid var(--border-subtle);
}

.idea-avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--bg-tertiary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 0.9rem;
  color: var(--accent-blue);
}

.idea-user {
  font-weight: 600;
  font-size: 0.9rem;
}

.idea-time {
  font-size: 0.75rem;
  color: var(--text-muted);
}

.idea-card-body {
  padding: 16px 20px;
}

.idea-card-body h3 {
  font-size: 1rem;
  font-weight: 700;
  margin-bottom: 8px;
}

.idea-card-body p {
  font-size: 0.85rem;
  color: var(--text-secondary);
  line-height: 1.5;
}

.idea-ticker-tag {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 10px;
  border-radius: 100px;
  background: var(--accent-blue-glow);
  color: var(--accent-blue);
  font-size: 0.75rem;
  font-weight: 600;
  margin-right: 6px;
  margin-top: 8px;
}

.idea-card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 20px;
  border-top: 1px solid var(--border-subtle);
}

.idea-stats {
  display: flex;
  gap: 16px;
  font-size: 0.78rem;
  color: var(--text-muted);
}

/* ===== BROKER CARDS ===== */
.brokers-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
  gap: 20px;
}

.broker-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 24px;
  transition: all var(--transition-base);
}
.broker-card:hover {
  border-color: var(--accent-blue);
  box-shadow: var(--shadow-lg);
}

.broker-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 16px;
}

.broker-name {
  font-size: 1.15rem;
  font-weight: 700;
}

.broker-tier {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 4px;
}

.broker-rating {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 12px;
}

.broker-score {
  font-size: 1.3rem;
  font-weight: 800;
}

.broker-label {
  font-size: 0.85rem;
  color: var(--text-secondary);
}

.broker-meta {
  display: flex;
  gap: 24px;
  margin-bottom: 16px;
  font-size: 0.8rem;
  color: var(--text-muted);
}

.broker-meta strong {
  color: var(--text-primary);
}

.broker-promo {
  padding: 10px 14px;
  background: var(--accent-blue-glow);
  border-radius: var(--radius-md);
  font-size: 0.8rem;
  color: var(--accent-blue);
  font-weight: 600;
}

/* ===== STATS BANNER ===== */
.stats-banner {
  background: linear-gradient(135deg, var(--bg-tertiary), var(--bg-secondary));
  border: 1px solid var(--border-color);
  border-radius: var(--radius-xl);
  padding: 40px 48px;
  text-align: center;
}

.stats-banner-grid {
  display: flex;
  justify-content: center;
  gap: 64px;
  flex-wrap: wrap;
}

.stats-banner-item h3 {
  font-size: 2rem;
  font-weight: 900;
  background: linear-gradient(135deg, var(--accent-blue), #64b5f6);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.stats-banner-item p {
  font-size: 0.85rem;
  color: var(--text-muted);
  margin-top: 4px;
}

/* ===== MARKET TABS SECTION ===== */
.market-tabs-scroll {
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  padding-bottom: 4px;
}

.market-tabs-scroll .tabs {
  flex-wrap: nowrap;
  min-width: max-content;
}

/* ===== SPARKLINE ===== */
.sparkline {
  width: 80px;
  height: 32px;
}

/* ===== FOOTER ===== */
.footer {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border-color);
  padding: 48px 24px 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 32px;
  max-width: 1400px;
  margin: 0 auto;
}

.footer-col h4 {
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--text-bright);
  margin-bottom: 12px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.footer-col a {
  display: block;
  font-size: 0.82rem;
  color: var(--text-muted);
  padding: 4px 0;
  transition: color var(--transition-fast);
}
.footer-col a:hover { color: var(--text-primary); }

.footer-bottom {
  text-align: center;
  padding-top: 32px;
  margin-top: 32px;
  border-top: 1px solid var(--border-subtle);
  font-size: 0.78rem;
  color: var(--text-muted);
}

/* ===== PAGINATION ===== */
.pagination {
  display: flex;
  justify-content: center;
  gap: 4px;
  margin-top: 32px;
}

.pagination button {
  width: 36px;
  height: 36px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border-color);
  background: transparent;
  color: var(--text-secondary);
  font-weight: 600;
  font-size: 0.85rem;
  cursor: pointer;
  transition: all var(--transition-fast);
}
.pagination button:hover {
  border-color: var(--accent-blue);
  color: var(--accent-blue);
}
.pagination button.active {
  background: var(--accent-blue);
  border-color: var(--accent-blue);
  color: #fff;
}

/* ===== NEWS CARDS ===== */
.news-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 20px;
}

.news-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 20px;
  cursor: pointer;
  transition: all var(--transition-base);
}
.news-card:hover {
  border-color: var(--accent-blue);
}

.news-card .source {
  font-size: 0.75rem;
  color: var(--accent-blue);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 8px;
}

.news-card h3 {
  font-size: 0.95rem;
  font-weight: 600;
  margin-bottom: 8px;
}

.news-card p {
  font-size: 0.82rem;
  color: var(--text-muted);
}

/* ===== SIDEBAR LAYOUTS ===== */
.sidebar-layout {
  display: grid;
  grid-template-columns: 1fr 340px;
  gap: 24px;
}

/* ===== UTILITY ===== */
.text-up { color: var(--gain-green); }
.text-down { color: var(--loss-red); }
.text-muted { color: var(--text-muted); }
.text-bright { color: var(--text-bright); }
.fw-bold { font-weight: 700; }
.fw-extrabold { font-weight: 800; }
.mt-1 { margin-top: 8px; }
.mt-2 { margin-top: 16px; }
.mt-3 { margin-top: 24px; }
.mb-1 { margin-bottom: 8px; }
.mb-2 { margin-bottom: 16px; }
.flex-between { display: flex; align-items: center; justify-content: space-between; }

/* ===== RESPONSIVE ===== */
@media (max-width: 1200px) {
  .chart-layout {
    grid-template-columns: 240px 1fr 280px;
  }
}

@media (max-width: 992px) {
  .chart-layout {
    grid-template-columns: 1fr;
    grid-template-rows: auto 1fr auto;
    height: auto;
  }
  .sidebar-layout {
    grid-template-columns: 1fr;
  }
  .detail-panel {
    border-left: none;
    border-top: 1px solid var(--border-color);
  }
  .hero h1 { font-size: 2rem; }
  .ideas-grid { grid-template-columns: 1fr; }
  .brokers-grid { grid-template-columns: 1fr; }
}

@media (max-width: 768px) {
  .nav-links { display: none; }
  .section { padding: 32px 16px; }
  .hero { padding: 48px 16px 36px; }
  .hero h1 { font-size: 1.6rem; }
  .hero p { font-size: 0.95rem; }
  .hero-stats { gap: 24px; }
  .market-bar-inner { gap: 0; }
  .market-item { padding: 10px 12px; }
  .stats-banner-grid { gap: 32px; }
  .chart-area { min-height: 300px; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 480px) {
  .hero h1 { font-size: 1.35rem; }
  .detail-price { font-size: 1.5rem; }
  .news-grid { grid-template-columns: 1fr; }
}

/* ===== SCROLLBAR ===== */
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: var(--bg-primary); }
::-webkit-scrollbar-thumb { background: var(--border-color); border-radius: 3px; }
::-webkit-scrollbar-thumb:hover { background: var(--text-muted); }

/* ===== EARNINGS CALENDAR ===== */
.earnings-table td.actual { color: var(--gain-green); font-weight: 600; }
.earnings-table td.estimate { color: var(--text-secondary); }

/* ===== INDICATOR/SIGNAL CARDS ===== */
.signal-card {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 20px;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  transition: all var(--transition-fast);
}
.signal-card:hover {
  border-color: var(--accent-blue);
}
.signal-badge {
  width: 36px;
  height: 36px;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 0.75rem;
  color: #fff;
  flex-shrink: 0;
}
.signal-info { flex: 1; min-width: 0; }
.signal-title { font-weight: 600; font-size: 0.88rem; }
.signal-meta { font-size: 0.75rem; color: var(--text-muted); }
.signal-chart { width: 60px; height: 28px; flex-shrink: 0; }

/* ===== GAINERS/LOSERS GRID ===== */
.movers-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}

/* ===== CRYPTO SUMMARY CARDS ===== */
.crypto-summary-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 16px;
}

.crypto-stat-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 16px 20px;
}

.crypto-stat-label {
  font-size: 0.75rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.crypto-stat-value {
  font-size: 1.2rem;
  font-weight: 800;
  font-family: var(--font-mono);
  margin-top: 4px;
}

/* ===== BONDS YIELD CURVE ===== */
.yield-list {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.yield-row {
  display: grid;
  grid-template-columns: 60px 1fr 80px 80px;
  gap: 12px;
  align-items: center;
  padding: 8px 12px;
  border-radius: var(--radius-sm);
  transition: background var(--transition-fast);
}
.yield-row:hover { background: rgba(255,255,255,0.03); }

.yield-bar-bg {
  height: 6px;
  background: var(--bg-input);
  border-radius: 3px;
  overflow: hidden;
}

.yield-bar-fill {
  height: 100%;
  border-radius: 3px;
  transition: width 0.5s ease;
}

/* ===== LIVE DOT ===== */
.live-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--gain-green);
  display: inline-block;
  animation: pulse 2s infinite;
}
@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.4; }
}

/* ===== WATCHLIST SIDEBAR PANEL ===== */
.watchlist-panel {
  background: var(--bg-secondary);
  border-right: 1px solid var(--border-color);
  overflow-y: auto;
}

/* Star icon */
.star { color: var(--warning-yellow); font-size: 0.75rem; }

/* ===== LOADING SKELETON ===== */
@keyframes shimmer {
  0% { background-position: -200% 0; }
  100% { background-position: 200% 0; }
}

.skeleton {
  background: linear-gradient(90deg, var(--bg-card) 25%, var(--bg-surface) 50%, var(--bg-card) 75%);
  background-size: 200% 100%;
  animation: shimmer 1.5s infinite;
  border-radius: var(--radius-sm);
}
