      ctx.moveTo(padding.left, gy);
      ctx.lineTo(w - padding.right, gy);
      ctx.stroke();

      // Price labels
      var priceLabel = maxPrice - (priceRange / 5) * i;
      ctx.fillStyle = '#6a6a80';
